ESTADO = {"S": "OPERATIVO", "N": "NO_OPERATIVO"}


def crear_equipos_de_radios(apps, schema_editor):
    """Un Equipo por radio, y mantenimientos, programaciones y alertas
    apuntando a ese Equipo."""
    Radio = apps.get_model("inventario", "Radio")
    Equipo = apps.get_model("inventario", "Equipo")
    usadas = set()
    for radio in Radio.objects.order_by("id"):
        placa = radio.placa or radio.id_inventario
        if placa in usadas:
            placa = radio.id_inventario
        usadas.add(placa)
        radio.equipo = Equipo.objects.create(
            placa=placa,
            tipo="RADIO",
            serial=radio.serial,
            marca=radio.marca,
            modelo=radio.modelo,
            fecha_compra=radio.fecha_compra,
            estado_operativo=ESTADO.get(radio.operativo, ""),
            activo=radio.activo,
            fecha_baja=radio.fecha_baja,
            motivo_baja=radio.motivo_baja,
            observaciones=radio.observaciones,
            requiere_revision=radio.requiere_revision,
            motivo_revision=radio.motivo_revision[:255],
        )
        radio.save(update_fields=["equipo"])

    for nombre in ("MantenimientoRadio", "MantenimientoProgramado",
                   "AlertaMantenimiento"):
        modelo = apps.get_model("inventario", nombre)
        for registro in modelo.objects.select_related("radio"):
            registro.equipo_id = registro.radio.equipo_id
            registro.save(update_fields=["equipo"])



